"""Read-only V3 report snapshot. Excludes model binaries, raw candles and private runtime."""
import argparse,json,hashlib,html,shutil
from pathlib import Path
from datetime import datetime,timezone
p=argparse.ArgumentParser();p.add_argument('--source',required=True);a=p.parse_args();src=Path(a.source).resolve();repo=Path(__file__).resolve().parent.parent;out=repo/'experiments/pepe-finrl-mask-v3';out.mkdir(parents=True,exist_ok=True)
files={'registration.json':src/'work/pepe-finrl-mask-v3/registration.json','parent-inventory.json':src/'work/pepe-finrl-mask-v3/parent-inventory.json','parent-selection.json':src/'work/pepe-finrl-mask-v3/parent-selection.json','parent-ranking.json':src/'web/data/pepe-mask-parent-scan.json','snapshot.json':src/'web/data/pepe-mask.json','cdi.json':src/'web/data/pepe-mask-cdi.json'}
manifest={}
for name,f in files.items():
 shutil.copyfile(f,out/name);manifest[name]=hashlib.sha256((out/name).read_bytes()).hexdigest()
state=json.loads((out/'snapshot.json').read_text());parent=json.loads((out/'parent-selection.json').read_text());cdi=json.loads((out/'cdi.json').read_text());esc=html.escape
brl=lambda n:'R$ '+f'{n:,.2f}'.replace(',','X').replace('.',',').replace('X','.')
row=lambda r:f'<tr><td>{esc(str(r["id"]))}</td><td>{brl(r["audit"]["pnlBRL"])}</td><td>{r["audit"]["maxDD"]*100:.2f}%</td><td>{r["audit"]["count"]}</td><td>{brl(r["score"])}</td></tr>'
ranking=json.loads((out/'parent-ranking.json').read_text())['ranking'];now=datetime.now(timezone.utc).isoformat()
body=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PEPE V3 · retrato da execução</title><style>body{{background:#101724;color:#e7edf7;font:16px/1.7 system-ui;max-width:1100px;margin:40px auto;padding:20px}}a{{color:#8acfff}}article{{background:#172234;padding:22px;border-radius:12px;margin:20px 0}}table{{width:100%;border-collapse:collapse;font-size:14px}}td,th{{padding:11px;border-bottom:1px solid #334157;text-align:left}}strong{{color:#7bdcba}}code{{overflow-wrap:anywhere}}</style><h1>PEPE V3 · auditoria contínua</h1><p>Retrato UTC: {esc(now)}. Não é acompanhamento ao vivo. <a href="http://127.0.0.1:4173/pesquisa-genetica/pepe-v3.html">Abrir o painel local</a>.</p><article><h2>Quatro correções</h2><ol><li>Campeões guardados com pesos exatos, hash, carteira, período, custos e linhagem antes de novo aprendizado.</li><li>Todos os 250 agentes auditados no mesmo trimestre contínuo antes da reprodução.</li><li>Sondagem de dois dias, auditoria fixa e final separados. Sem composição de janelas reiniciadas.</li><li>MaskablePPO: ações válidas por estado no treino e na avaliação.</li></ol></article><article><h2>Pai inicial</h2><p><strong>{esc(parent['candidate'])}</strong>: {parent['evaluated']} arquivos distintos comparados no mesmo calendário outubro–dezembro/2024 com custos de estresse. Líquido <strong>{brl(parent['audit']['pnlBRL'])}</strong>, quatro posições, queda máxima {parent['audit']['maxDD']*100:.2f}%. CDI bruto: {brl(cdi['pnlBRL'])}. Amostra pequena e escolha entre muitos candidatos: não é prova de lucro futuro.</p><p>Política transferida com {parent['transfer']['parameters']} parâmetros idênticos; novo otimizador. SHA convertido: <code>{esc(parent['archive']['modelSHA256'])}</code>.</p></article><article><h2>Execução no retrato</h2><p>Estado: {esc(state['status'])}; geração {state['generation']} de 1000; {state.get('jobsCompleted',0)} de 250 trabalhos na geração atual. Três workers, risco 1%, alavancagem 10×/15×, limites de perdas preservados.</p><p>Teste final V3: <strong>bloqueado</strong>, depende de um novo calendário prospectivo. O teste antigo já foi observado e não é reutilizado como prova independente.</p></article><article><h2>Melhores pesos recuperáveis na varredura</h2><table><thead><tr><th>Candidato</th><th>Líquido</th><th>Queda</th><th>Posições</th><th>Score</th></tr></thead><tbody>{''.join(row(r)for r in ranking[:20])}</tbody></table></article><p><a href="snapshot.json">Estado completo</a> · <a href="parent-ranking.json">Todos os candidatos</a> · <a href="registration.json">Registro científico</a> · <a href="../../app/PEPE-V3-AUDITORIA.md">Método</a></p><p>Modelos e dados volumosos permanecem na máquina; este repositório privado contém código, evidências numéricas e hashes. Sem ordens reais. Antes de impostos.</p></html>'''
(out/'index.html').write_text(body);(out/'snapshot-manifest.json').write_text(json.dumps({'createdAt':now,'files':manifest,'modelsIncluded':False,'rawMarketDataIncluded':False,'note':'Read-only source snapshot; not a final-test evaluation.'},indent=2)+'\n');print(json.dumps({'snapshot':str(out.relative_to(repo)),'generation':state['generation'],'status':state['status']}))
